export const UI_LANGUAGES=[{"code": "ar", "name": "العربية"}, {"code": "en", "name": "English"}, {"code": "fr", "name": "Français"}, {"code": "de", "name": "Deutsch"}, {"code": "es", "name": "Español"}, {"code": "tr", "name": "Türkçe"}];
export const OCR_LANGUAGES=[{"code": "ara", "name": "العربية", "tag": "ar"}, {"code": "eng", "name": "English", "tag": "en"}, {"code": "fra", "name": "Français", "tag": "fr"}, {"code": "deu", "name": "Deutsch", "tag": "de"}, {"code": "spa", "name": "Español", "tag": "es"}, {"code": "tur", "name": "Türkçe", "tag": "tr"}, {"code": "ita", "name": "Italiano", "tag": "it"}, {"code": "por", "name": "Português", "tag": "pt"}, {"code": "rus", "name": "Русский", "tag": "ru"}, {"code": "fas", "name": "فارسی", "tag": "fa"}, {"code": "hin", "name": "हिन्दी", "tag": "hi"}, {"code": "chi_sim", "name": "简体中文", "tag": "zh"}, {"code": "jpn", "name": "日本語", "tag": "ja"}, {"code": "kor", "name": "한국어", "tag": "ko"}];
export function validateOcrLanguage(value){const parts=String(value).split("+");if(!parts.length||parts.length>3||new Set(parts).size!==parts.length||parts.some(p=>!OCR_LANGUAGES.some(l=>l.code===p)))throw Error("اختر لغة استخراج نص مدعومة");return parts.join("+");}
